CREATE VIEW [Security].[TenantRoll_Ledger_Ledger] AS			SELECT [Id], [TenantId], [RollId], [ledger_start_time], [ledger_end_time], [ledger_start_transaction_id] AS [ledger_transaction_id], [ledger_start_sequence_number] AS [ledger_sequence_number], 1 AS [ledger_operation_type], N'INSERT' AS [ledger_operation_type_desc] FROM [Security].[TenantRoll]			UNION ALL			SELECT [Id], [TenantId], [RollId], [ledger_start_time], CONVERT(DATETIME2(7), SYSMAXDATETIME(CONVERT(SMALLINT, 7))) AS [ledger_end_time], [ledger_start_transaction_id] AS [ledger_transaction_id], [ledger_start_sequence_number] AS [ledger_sequence_number], 1 AS [ledger_operation_type], N'INSERT' AS [ledger_operation_type_desc] FROM [Security].[TenantRoll_Ledger_History]			UNION ALL			SELECT [Id], [TenantId], [RollId], [ledger_start_time], [ledger_end_time], [ledger_end_transaction_id] AS [ledger_transaction_id], [ledger_end_sequence_number] AS [ledger_sequence_number], 2 AS [ledger_operation_type], N'DELETE' AS [ledger_operation_type_desc] FROM [Security].[TenantRoll_Ledger_History]